const SCALE = 171.542202;
const TX = 500.000000;
const TY = 250.000000;

/** Proyección Natural Earth I: convierte [longitud, latitud] en coordenadas [x, y] del mapa. */
export function projectPoint(lon: number, lat: number): [number, number] {
  const lambda = (lon * Math.PI) / 180;
  const phi = (lat * Math.PI) / 180;
  const phi2 = phi * phi;
  const phi4 = phi2 * phi2;
  const x = lambda * (0.8707 - 0.131979 * phi2 + phi4 * (-0.013791 + phi4 * (0.003971 * phi2 - 0.001529 * phi4)));
  const y = phi * (1.007226 + phi2 * (0.015085 + phi4 * (-0.044475 + 0.028874 * phi2 - 0.005916 * phi4)));
  return [TX + SCALE * x, TY - SCALE * y];
}

